class MaxHeap {
  constructor() { this.heap = []; }
  push(v) { this.heap.push(v); this.bubbleUp(this.heap.length - 1); }
  pop() {
    const top = this.heap[0];
    this.heap[0] = this.heap.pop();
    this.bubbleDown(0);
    return top;
  }
  peek() { return this.heap[0]; }
  get size() { return this.heap.length; }
  bubbleUp(i) {
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (this.heap[p] >= this.heap[i]) break;
      [this.heap[p], this.heap[i]] = [this.heap[i], this.heap[p]];
      i = p;
    }
  }
  bubbleDown(i) {
    while (true) {
      const l = 2*i+1, r = 2*i+2;
      let max = i;
      if (l < this.heap.length && this.heap[l] > this.heap[max]) max = l;
      if (r < this.heap.length && this.heap[r] > this.heap[max]) max = r;
      if (max === i) break;
      [this.heap[i], this.heap[max]] = [this.heap[max], this.heap[i]];
      i = max;
    }
  }
}
class MinHeap {
  constructor() { this.heap = []; }
  push(v) { this.heap.push(v); this.bubbleUp(this.heap.length - 1); }
  pop() {
    const top = this.heap[0];
    this.heap[0] = this.heap.pop();
    this.bubbleDown(0);
    return top;
  }
  peek() { return this.heap[0]; }
  get size() { return this.heap.length; }
  bubbleUp(i) {
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (this.heap[p] <= this.heap[i]) break;
      [this.heap[p], this.heap[i]] = [this.heap[i], this.heap[p]];
      i = p;
    }
  }
  bubbleDown(i) {
    while (true) {
      const l = 2*i+1, r = 2*i+2;
      let min = i;
      if (l < this.heap.length && this.heap[l] < this.heap[min]) min = l;
      if (r < this.heap.length && this.heap[r] < this.heap[min]) min = r;
      if (min === i) break;
      [this.heap[i], this.heap[min]] = [this.heap[min], this.heap[i]];
      i = min;
    }
  }
}
function MedianFinder() {
  this.lo = new MaxHeap(); this.hi = new MinHeap();
}
MedianFinder.prototype.addNum = function(num) {
  this.lo.push(num);
  this.hi.push(this.lo.pop());
  if (this.lo.size < this.hi.size) this.lo.push(this.hi.pop());
};
MedianFinder.prototype.findMedian = function() {
  return this.lo.size > this.hi.size ? this.lo.peek() : (this.lo.peek() + this.hi.peek()) / 2;
};

solution.cpp:
class MedianFinder {
    priority_queue<int> lo;
    priority_queue<int, vector<int>, greater<int>> hi;
public:
    void addNum(int num) {
        lo.push(num);
        hi.push(lo.top()); lo.pop();
        if (lo.size() < hi.size()) { lo.push(hi.top()); hi.pop(); }
    }
    double findMedian() {
        return lo.size() > hi.size() ? lo.top() : (lo.top() + hi.top()) / 2.0;
    }
};
